/* * <pwd.h> for OS-9. * * OS-9 has no /etc/passwd: a user is a group.user number pair, and the name * lives in the password file only if the system runs login.  This declares * just the shape the shim in shims/os9getpw.c fills in, which is all any * program on this disk actually reads. */struct passwd {    char *pw_name;    char *pw_passwd;    int   pw_uid;    int   pw_gid;    char *pw_gecos;    char *pw_dir;    char *pw_shell;    /* OS-9's password file carries three things Unix's does not: the     * initial process priority, the EXECUTION directory as distinct     * from the data directory, and the single packed group.user id --     * group in the high half, user in the low -- which is what getuid()     * returns and what callers compare an entry against.  blarslib's     * getpw.c fills the first two; uucp_blars' uuxqt.c reads the third.     * Added 2026-08-23.     */    int   pw_priority;    char *pw_xdir;    int   pw_giduid;};struct passwd *getpwuid();struct passwd *getpwnam();